(-5, 'contact.php', '<?php\r\nclass Contact {\r\n\r\n    function PokazKontakt(){\r\n        $wynik = \'\r\n        <div class=\"contact\">\r\n            <form method = \"post\" name=\"LoginForm\" enctype=\"multipart/form-data\" action\"\'.$_SERVER[\'REQUEST_URI\'].\'\">\r\n                <table class=\"contact\">\r\n                    <tr><td class=\"zaw\">Email: </td><td><input type=\"text\"  class=\"contact\" /></td></tr>\r\n                    <tr><td class=\"zaw\">Tytuł: </td><td><input type=\"text\"  class=\"contact\" /></td></tr>\r\n                    <tr>\r\n                    <td>Zawartość:</td>\r\n                    <td class=\"zaw\"><textarea></textarea></td>\r\n                    </tr>\r\n                    <tr><td></td><td><input type=\"submit\" class=\"send-button\" value=\"wyślij\" /></td></tr>\r\n                </table>\r\n            </form>\r\n        </div>\r\n        \r\n        \';\r\n        return $wynik;\r\n    }\r\n\r\n    function PokazHaslo(){\r\n        $wynik = \'\r\n        <div class=\"passrecov\">\r\n			<div class=\"passrecov\">\r\n				<form method=\"post\" name=\"LoginForm\" enctype=\"multipart/form-data\" action=\"\'.$_SERVER[\'REQUEST_URI\'].\'\">\r\n					<table class=\"passrecov\">\r\n						<tr><td class=\"log4_t\">Email: </td><td><input type=\"text\" name=\"email_recov\" class=\"passrecov\" /></td></tr>\r\n						<tr><td></td><td><input type=\"submit\" name=\"x1_submit\" class=\"passrecov\" value=\"wyślij\" /></td></tr>\r\n					</table>\r\n				</form>\r\n			 </div>\r\n		</div>\r\n		\';\r\n		return $wynik;\r\n    }\r\n\r\n    function WyslijMailKontakt($odbiorca){\r\n        if(empty($_POST[\'email\']) || empty($_POST[\'title\']) || empty($_POST[\'content\'])) {\r\n            echo $this->PokazKontakt();\r\n        }\r\n        else {\r\n            $mail[\'subject\']   = $_POST[\'temat\'];\r\n            $mail[\'body\']      = $_POST[\'tresc\'];\r\n            $mail[\'sender\']    = $_POST[\'email\'];\r\n            $mail[\'recipient\'] = $odbiorca;\r\n            \r\n            $header  = \"From: Fromularz kontaktowy <\".$mail[\'sender\'].\">\\n\";\r\n            $header .= \"MIME-Version: 1.0\\nContent-Type: text/plain; charset-utf-8\\nContent-Transfer-Encoding: \";\r\n			$header .= \"X-Sender: <\".$mail[\'sender\'].\">\\n\";\r\n			$header .= \"X-Mailer: prapwww mail 1.2\\n\";\r\n			$header .= \"X-Priority: 3\\n\";\r\n			$header .= \"Return-Path: <\".$mail[\'sender\'].\">\\n\";\r\n\r\n            mail($mail[\'recipient\'],$mail[\'subject\'],$mail[\'body\'], $header);\r\n\r\n            echo \'Wiadomość wysłana\';\r\n        }\r\n    }\r\n    \r\n    \r\n    \r\n    function PrzypomnijHaslo($odbiorca){\r\n        if(empty($_POST[\'email_recovery\'])) {														// Czy nie został wprowadzony email?\r\n			echo $this->PokazHaslo();															// Wyświetl pole emaila do wypełnienia\r\n		}\r\n\r\n        else {\r\n			$mail[\'sender\']			= $_POST[\'email_recovery\'];\r\n			$mail[\'subject\']		= \"Password Recovery\";\r\n			$mail[\'body\']			= \"Password = haslo\";\r\n			$mail[\'recipient\']		= $odbiorca;\r\n			\r\n			$header  = \"From: Forumularz kontaktowy <\".$mail[\'sender\'].\">\\n\";\r\n			$header .= \"MIME-Version: 1.0\\nContent-Type: text/plain; charset-utf-8\\nContent-Transfer-Encoding: \";\r\n			$header .= \"X-Sender: <\".$mail[\'sender\'].\">\\n\";\r\n			$header .= \"X-Mailer: prapwww mail 1.2\\n\";\r\n			$header .= \"X-Priority: 3\\n\";\r\n			$header .= \"Return-Path: <\".$mail[\'sender\'].\">\\n\";\r\n			\r\n			mail($mail[\'recipient\'],$mail[\'subject\'],$mail[\'body\'],$header);					// Wysłanie emaila z hasłem\r\n			\r\n			echo \'Hasło wysłane\';\r\n		}\r\n\r\n    }\r\n}\r\n?>', 1, 'kontakt'),
(1, 'main.html', '    <section>\r\n        <h1>Największe budynki na świecie</h1>\r\n\r\n        <div class=\"intro\">\r\n            <p>Witamy na stronie poświęconej największym budynkom świata. Człowiek od wieków dąży do budowania coraz wyższych konstrukcji, a dzisiejsze wieżowce osiągają wysokości przekraczające 800 metrów.</p>\r\n            <p>Tutaj znajdziesz informacje o najwyższych budynkach, ich historii oraz technologiach, które umożliwiły ich powstanie.</p>\r\n        </div>\r\n\r\n        <div class=\"section\">\r\n            <h2>Rekordowe wysokości</h2>\r\n            <p>Burj Khalifa w Dubaju to obecnie najwyższy budynek świata z wysokością 828 metrów. Ma 163 piętra i został ukończony w 2010 roku.</p>\r\n            <p>Na drugim miejscu znajduje się Merdeka 118 w Kuala Lumpur (679 metrów), a na trzecim Shanghai Tower w Chinach (632 metry).</p>\r\n        </div>\r\n\r\n        <div class=\"section\">\r\n            <h2>Gdzie znajdują się największe budynki?</h2>\r\n            <p>Większość najwyższych budynków świata znajduje się w Azji i na Bliskim Wschodzie. Dubaj, Szanghaj, Kuala Lumpur i Hongkong to miasta z największą liczbą drapaczy chmur.</p>\r\n            <p>W Ameryce Północnej najwyższym budynkiem jest One World Trade Center w Nowym Jorku (541 metrów).</p>\r\n        </div>\r\n\r\n        <div class=\"section\">\r\n            <h2>Technologia i bezpieczeństwo</h2>\r\n            <p>Budowanie tak wysokich konstrukcji wymaga zaawansowanych technologii. Wykorzystuje się specjalne materiały, systemy stabilizacji oraz technologie chroniące przed wiatrem i trzęsieniami ziemi.</p>\r\n            <p>Nowoczesne wieżowce są również projektowane z myślą o ekologii i efektywności energetycznej.</p>\r\n        </div>\r\n\r\n        <div class=\"section\">\r\n            <h2>Ciekawostki</h2>\r\n            <p>Empire State Building przez 40 lat był najwyższym budynkiem świata (1931-1971). Jego budowa trwała zaledwie 13 miesięcy.</p>\r\n            <p>W planach są budynki, które przekroczą kilometr wysokości. Jeddah Tower w Arabii Saudyjskiej ma osiągnąć 1000 metrów.</p>\r\n        </div>\r\n    </section>\r\n\r\n ', 1, 'main'),
(2, 'budynki.html', '\r\n\r\n     <section>\r\n        <h1>Trochę o gigantach</h1>\r\n\r\n        <div class=\"intro\">\r\n            <p>Odkryj najwspanialsze architektoniczne osiągnięcia ludzkości. Poniżej znajdziesz szczegółowe informacje o najwyższych budynkach świata, ich charakterystyce oraz historii powstania.</p>\r\n        </div>\r\n        \r\n        <div class=\"building-card\">\r\n            \r\n            <h2>1. Burj Khalifa - Dubaj (ZEA)</h2>\r\n            <img src=\"pics/Burj_Khalifa.jpg\" alt=\"logo\"> \r\n            <div class=\"building-info\">\r\n                <p><strong>Wysokość:</strong> 828 m</p>\r\n                <p><strong>Liczba pięter:</strong> 163</p>\r\n                <p><strong>Rok ukończenia:</strong> 2010</p>\r\n            </div>\r\n            <p>Burj Khalifa to najwyższy budynek świata, który dominuje nad panoramą Dubaju. Wieżowiec zawiera mieszkania, biura, hotele oraz obserwatorium. Jego budowa trwała 6 lat i wymagała zaangażowania tysięcy pracowników. Budynek jest połączony z nowoczesnym systemem zarządzania energią i klimatyzacją.</p>\r\n        </div>\r\n\r\n        <div class=\"building-card\">\r\n            <h2>2. Merdeka 118 - Kuala Lumpur (Malezja)</h2>\r\n            <img src=\"pics/Merdeka_118.jpg\" alt=\"logo\"> \r\n            <div class=\"building-info\">\r\n                <p><strong>Wysokość:</strong> 679 m</p>\r\n                <p><strong>Liczba pięter:</strong> 118</p>\r\n                <p><strong>Rok ukończenia:</strong> 2023</p>\r\n            </div>\r\n            <p>Merdeka 118 to drugi najwyższy budynek na świecie i największe osiągnięcie architektoniczne Malezji. Nowoczesna wieża łączy funkcje biurowe, hotelowe i handlowe. Budynek wyróżnia się zrównoważonym podejściem do projektowania, z systemami oszczędzającymi energię i zbierającymi deszczówkę.</p>\r\n        </div>\r\n\r\n        <div class=\"building-card\">\r\n            <h2>3. Shanghai Tower - Szanghaj (Chiny)</h2>\r\n            <img src=\"pics/Shanghai_Tower.jpg\" alt=\"logo\"> \r\n            <div class=\"building-info\">\r\n                <p><strong>Wysokość:</strong> 632 m</p>\r\n                <p><strong>Liczba pięter:</strong> 128</p>\r\n                <p><strong>Rok ukończenia:</strong> 2015</p>\r\n            </div>\r\n            <p>Shanghai Tower jest trzecim najwyższym budynkiem świata i symbolem nowoczesnego Szanghaju. Wieżowiec posiada unikalne obracające się spiralne profile, które zmniejszają opór wiatru. Zawiera biura, hotele, sklepy i obserwatorium. Budynek spełnia najwyższe normy bezpieczeństwa sejsmicznego i energetycznego.</p>\r\n        </div>\r\n\r\n        <div class=\"building-card\">\r\n            <h2>4. Abraj Al-Bait Clock Tower - Mekka (Arabia Saudyjska)</h2>\r\n            <img src=\"pics/Abraj_Al_Bait_Tower.jpg\" alt=\"logo\"> \r\n            <div class=\"building-info\">\r\n                <p><strong>Wysokość:</strong> 601 m</p>\r\n                <p><strong>Liczba pięter:</strong> 120</p>\r\n                <p><strong>Rok ukończenia:</strong> 2012</p>\r\n            </div>\r\n            <p>Wieża zegarowa Abraj Al-Bait to czwarty najwyższy budynek świata, znajdujący się w bezpośredniej bliskości Wielkiego Meczetu w Mekce. Budynek zawiera 4 ogromne tarcze zegarowe, które są widoczne z odległości do 25 km. Kompleks zapewnia mieszkania dla pielgrzymów i zawiera luksusowy hotel.</p>\r\n        </div>\r\n\r\n        <div class=\"building-card\">\r\n            <h2>5. Ping An International Finance Centre - Shenzhen (Chiny)</h2>\r\n            <img src=\"pics/Pingan_International_Finance_Center.jpg\" alt=\"logo\"> \r\n            <div class=\"building-info\">\r\n                <p><strong>Wysokość:</strong> 599 m</p>\r\n                <p><strong>Liczba pięter:</strong> 115</p>\r\n                <p><strong>Rok ukończenia:</strong> 2017</p>\r\n            </div>\r\n            <p>Ping An International Finance Centre to piąty najwyższy budynek świata, będący siedzibą grupy Ping An. Wieżowiec łączy biura, hotel i mall handlowy. Budynek wykorzystuje najnowszą technologię w zarządzaniu budynkiem inteligentnym oraz systemami bezpieczeństwa.</p>\r\n        </div>\r\n\r\n        <div class=\"section\">\r\n            <h2>Inżynierskie wyzwania</h2>\r\n            <p>Budowanie tak wysokich konstrukcji to ogromne wyzwanie inżynieryjne. Każdy z tych budynków musi być odporny na silne wiatry, trzęsienia ziemi i ekstremalne temperatury. Konstruktorzy używają zaawansowanych materiałów, takich jak stal wysokiej jakości i specjalne betony.</p>\r\n            <p>Systemy stabilizacji dynamicznej, widoczne szczególnie w Shanghai Tower i Burj Khalifa, pozwalają budynkom elastycznie reagować na siły zewnętrzne, zapewniając bezpieczeństwo mieszkańcom i pracownikom.</p>\r\n        </div>\r\n\r\n        <div class=\"section\">\r\n            <h2>Zrównoważony rozwój</h2>\r\n            <p>Nowoczesne wieżowce coraz bardziej skupiają się na zrównoważonym rozwoju. Merdeka 118 i Shanghai Tower zostały zaprojektowane z myślą o minimalizacji zużycia energii. Wykorzystują panele słoneczne, systemy gromadzenia deszczówki i zaawansowaną klimatyzację.</p>\r\n            <p>Takie podejście nie tylko zmniejsza koszty operacyjne, ale również przyczynia się do ochrony środowiska dla przyszłych pokoleń.</p>\r\n        </div>\r\n    </section>\r\n\r\n', 1, 'budynki'),
(3, 'ranking.html', '    <section>\r\n        <h1>Ranking najwyższych budynków świata</h1>\r\n        <div class=\"ranking-table\">\r\n            <table>\r\n                <thead>\r\n                    <tr>\r\n                        <th class=\"center\">Miejsce</th>\r\n                        <th>Nazwa budynku</th>\r\n                        <th>Miasto</th>\r\n                        <th>Kraj</th>\r\n                        <th class=\"center\">Wysokość</th>\r\n                        <th class=\"center\">Piętra</th>\r\n                        <th class=\"center\">Rok</th>\r\n                    </tr>\r\n                </thead>\r\n                <tbody>\r\n                    <tr>\r\n                        <td class=\"center\"><span class=\"rank rank-1\">1</span></td>\r\n                        <td class=\"building-name\">Burj Khalifa</td>\r\n                        <td>Dubaj</td>\r\n                        <td>ZEA</td>\r\n                        <td class=\"center height\">828 m</td>\r\n                        <td class=\"center\">163</td>\r\n                        <td class=\"center\">2010</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td class=\"center\"><span class=\"rank rank-2\">2</span></td>\r\n                        <td class=\"building-name\">Merdeka 118</td>\r\n                        <td>Kuala Lumpur</td>\r\n                        <td>Malezja</td>\r\n                        <td class=\"center height\">679 m</td>\r\n                        <td class=\"center\">118</td>\r\n                        <td class=\"center\">2023</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td class=\"center\"><span class=\"rank rank-3\">3</span></td>\r\n                        <td class=\"building-name\">Shanghai Tower</td>\r\n                        <td>Szanghaj</td>\r\n                        <td>Chiny</td>\r\n                        <td class=\"center height\">632 m</td>\r\n       