       <td class=\"center\">94</td>\r\n                        <td class=\"center\">2014</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td class=\"center\"><span class=\"rank\">8</span></td>\r\n                        <td class=\"building-name\">Guangzhou CTF Finance Centre</td>\r\n                        <td>Guangzhou</td>\r\n                        <td>Chiny</td>\r\n                        <td class=\"center height\">530 m</td>\r\n                        <td class=\"center\">111</td>\r\n                        <td class=\"center\">2016</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td class=\"center\"><span class=\"rank\">9</span></td>\r\n                        <td class=\"building-name\">Tianjin CTF Finance Centre</td>\r\n                        <td>Tianjin</td>\r\n                        <td>Chiny</td>\r\n                        <td class=\"center height\">530 m</td>\r\n                        <td class=\"center\">97</td>\r\n                        <td class=\"center\">2019</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td class=\"center\"><span class=\"rank\">10</span></td>\r\n                        <td class=\"building-name\">China Zun</td>\r\n                        <td>Pekin</td>\r\n                        <td>Chiny</td>\r\n                        <td class=\"center height\">528 m</td>\r\n                        <td class=\"center\">108</td>\r\n                        <td class=\"center\">2018</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td class=\"center\"><span class=\"rank\">11</span></td>\r\n                        <td class=\"building-name\">Taipei 101</td>\r\n                        <td>Tajpej</td>\r\n                        <td>Tajwan</td>\r\n                        <td class=\"center height\">508 m</td>\r\n                        <td class=\"center\">101</td>\r\n                        <td class=\"center\">2004</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td class=\"center\"><span class=\"rank\">12</span></td>\r\n                        <td class=\"building-name\">Shanghai World Financial Center</td>\r\n                        <td>Szanghaj</td>\r\n                        <td>Chiny</td>\r\n                        <td class=\"center height\">492 m</td>\r\n                        <td class=\"center\">101</td>\r\n                        <td class=\"center\">2008</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td class=\"center\"><span class=\"rank\">13</span></td>\r\n                        <td class=\"building-name\">International Commerce Centre</td>\r\n                        <td>Hongkong</td>\r\n                        <td>Chiny</td>\r\n                        <td class=\"center height\">484 m</td>\r\n                        <td class=\"center\">108</td>\r\n                        <td class=\"center\">2010</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td class=\"center\"><span class=\"rank\">14</span></td>\r\n                        <td class=\"building-name\">Central Park Tower</td>\r\n                        <td>Nowy Jork</td>\r\n                        <td>USA</td>\r\n                        <td class=\"center height\">472 m</td>\r\n                        <td class=\"center\">98</td>\r\n                        <td class=\"center\">2020</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td class=\"center\"><span class=\"rank\">15</span></td>\r\n                        <td class=\"building-name\">Lakhta Center</td>\r\n                        <td>Sankt Petersburg</td>\r\n                        <td>Rosja</td>\r\n                        <td class=\"center height\">462 m</td>\r\n                        <td class=\"center\">87</td>\r\n                        <td class=\"center\">2019</td>\r\n                    </tr>\r\n                </tbody>\r\n            </table>\r\n        </div>\r\n    </section>\r\n\r\n', 1, 'ranking'),
(5, 'architektura.html', '    <section>\r\n        <h1>Architektura najwyższych budynków świata - gdy technologia sięga chmur</h1>\r\n\r\n        <div class=\"intro\">\r\n            <p>Współczesna architektura od dawna przekracza granice ludzkiej wyobraźni. Wieżowce, które jeszcze kilka dekad temu wydawały się niemożliwe do zbudowania, dziś stanowią wizytówki światowych metropolii.\r\n                 Rywalizacja o tytuł najwyższego budynku świata to nie tylko pokaz siły technologicznej, lecz także symbol postępu i ambicji.</p>\r\n        </div>\r\n\r\n        <div class=\"section\">\r\n            <p>Burj Khalifa w Dubaju (828 m) od 2010 roku króluje na szczycie tej listy. Jego smukła, stopniowo zwężająca się konstrukcja inspirowana jest kwiatem Hymenocallis. Wykonana z betonu i stali, łączy w sobie nowoczesność i elegancję pustynnej kultury Zatoki Perskiej.\r\n\r\n            Tuż za nim w kolejce stoją giganty nowej generacji, takie jak Merdeka 118 w Kuala Lumpur (678,9 m) czy budowany Jeddah Tower w Arabii Saudyjskiej, który ma przekroczyć magiczny próg 1000 metrów. Ich projekty wykorzystują zaawansowane technologie aerodynamiczne, by zminimalizować wpływ wiatru i zwiększyć stabilność konstrukcji.\r\n\r\n            Wysokość to jednak nie wszystko. Dzisiejsze drapacze chmur stają się mikroświatami — z mieszkalnymi apartamentami, biurami, hotelami, a nawet ogrodami i przestrzeniami rekreacyjnymi na setkach metrów nad ziemią. Coraz większy nacisk kładzie się także na zrównoważony rozwój – panele słoneczne, inteligentne systemy wentylacji i odzysk wody deszczowej stają się standardem.\r\n\r\n            Architektura najwyższych budynków świata to nie tylko wyścig o metry - to opowieść o ludzkiej kreatywności, ambicji i pragnieniu, by dosłownie sięgnąć nieba.</p>\r\n\r\n        </div>\r\n    </section>\r\n', 1, 'architektura'),
(6, 'filmy.html', '<h3>Zobacz film o najwiekszych budynkach świata</h3>\r\n<div class=\"video\">\r\n    <iframe width=\"560\" height=\"315\" src=\"https://www.youtube.com/embed/uILx3tLS7hQ\"\r\n        title=\"YouTube video player\" frameborder=\"0\"\r\n        allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\"\r\n        referrerpolicy=\"strict-origin-when-cross-origin\" allowfullscreen></iframe>\r\n</div>', 1, 'filmy'),
(7, 'SkryptyJS.html', '    <section onload=\"startclock()\">\r\n        <div id=\'skrypt_jeden\'>\r\n                    <p>Kliknij przycisk, aby zmienić kolor tła strony.</p>\r\n                    <form method=\'post\' name=\'background\'>\r\n                        <button type=\'button\' onclick=\'changeBackground(\"#FFF000\")\'>Żółty</button>\r\n                        <button type=\'button\' onclick=\'changeBackground(\"#000000\")\'>Czarny</button>\r\n                        <button type=\'button\' onclick=\'changeBackground(\"#FFFFFF\")\'>Biały</button>\r\n                        <button type=\'button\' onclick=\'changeBackground(\"#00FF00\")\'>Zielony</button>\r\n                        <button type=\'button\' onclick=\'changeBackground(\"#0000FF\")\'>Niebieski</button>\r\n                        <button type=\'button\' onclick=\'changeBackground(\"#FF8000\")\'>Pomarańczowy</button>\r\n                        <button type=\'button\' onclick=\'changeBackground(\"#C0C0C0\")\'>Szary</button>\r\n                        <button type=\'button\' onclick=\'changeBackground(\"#FF0000\")\'>Czerwony</button>\r\n                        <button type=\'button\' onclick=\'changeBackground(getRandomColor())\'>Losowy kolor</button>\r\n                    </form>\r\n        </div>\r\n    </section>', 1, 'skryptyJS'),
(8, 'JQuary.html', '    <section>\r\n        <h2>jQuery</h2>\r\n        <div id=\"animacjaTestowa1\" class=\"test-block\">\r\n            Kliknij, a się powiększe\r\n        </div>\r\n        <script>\r\n            $(\"#animacjaTestowa1\").on(\"click\", function() {\r\n                $(this).animate({\r\n                    width: \"500px\",\r\n                    opacity: 0.4,\r\n                    fontSize: \"3em\",\r\n                    borderwidth: \"10px\"\r\n                }, 1500)\r\n            })\r\n        </script>\r\n\r\n        <div id=\"animacjaTestowa2\" class=\"test-block\">\r\n            Najedź kursorem. a się powiększe\r\n        </div>\r\n        <script>\r\n            $(\"#animacjaTestowa2\").on({\r\n                \"mouseover\" : function(){\r\n                    $(this).animate({\r\n                        width: 300\r\n                    }, 800)\r\n                },\r\n                \"mouseout\" : function(){\r\n                    $(this).animate({\r\n                        width: 200\r\n                    }, 800)\r\n                }\r\n            })\r\n        </script>\r\n        <div id=\"animacjaTestowa3\" class=\"test-block\">\r\n            Kliknij, abym urósł\r\n        </div>\r\n        <script>\r\n            $(\"#animacjaTestowa3\").on(\"click\", function(){\r\n                if (!$(this).is(\":animated\")){\r\n                    $(this).animate({\r\n                        width: \"+=\" + 50,\r\n                        height: \"+=\" + 10,\r\n                        opacity: \"+=\" + 0.1,\r\n                        duration: 3000\r\n                    })\r\n                }\r\n            })\r\n        </script>\r\n    </section>\r\n\r\n', 1, 'jquary'),
(10, 'lab4.html', '<?php\r\n$nr_indeksu = \'175281\';\r\n$nrGrupy = \'ISI2\';\r\n\r\necho \"Paweł Milanowski $nr_indeksu $nrGrupy\";\r\necho \"<br>Zastosowanie metody include()<br>\";\r\n\r\ninclude(\'test_include.php\');\r\ntest_include();\r\nrequire_once(\'test_require_once.php\');\r\ntest_require_once();\r\n\r\n?>\r\n\r\n<form action=\"labor_175281_ISI2.php\" method=\"get\">\r\n    <label for=\"val1\">Podaj liczbę</label>\r\n    <input type=\"number\" name=\"val1\" id=\"val1\">\r\n    <button type=\"submit\">Wyślij</button>\r\n</form>\r\n\r\n\r\n<?php\r\nif(!empty($_GET[\'val1\'])){\r\n    $value = $_GET[\'val1\'];\r\n} else {\r\n    $value = 23;\r\n}\r\nif ($value == 0) {\r\n    echo \"<p>Liczba $value to zero</p>\";\r\n} else if ($value % 2 == 0) {\r\n    echo \"<p>Liczba $value jest parzysta</p>\";\r\n} else {\r\n    echo \"<p>Liczba $value jest nieparzysta</p>\";\r\n}\r\n\r\n\r\necho \"<p>Pętla while<p>\";\r\nwhile ($value > 0) {\r\n    echo \"$value<br>\";\r\n    $value = $value - 3;\r\n}\r\n\r\necho \"<p>Pętla for<p>\";\r\nfor($i = 10; $i!=0; $i--){\r\n    echo \"$i<br>\";\r\n}\r\n\r\n?>\r\n\r\n<form action=\"labor_175281_ISI2.php\" method=\"post\">\r\n    <label for=\"val2\">Podaj liczbę</label>\r\n    <input type=\"number\" name=\"val2\" id=\"val2\">\r\n    <button type=\"submit\">Wyślij</button>\r\n</form>\r\n\r\n<?php\r\nif (!empty($_POST[\'val2\'])){\r\n    $value2 = $_POST[\'val2\'];\r\n} else {\r\n    $value2 = rand(0, 10);\r\n}\r\nswitch ($value2) {\r\n    case ($value2 % 2 == 0):\r\n        echo \"<p>$value2 jest podzielne przez 2</p>\";\r\n        break;\r\n    case ($value2 % 3 == 0):\r\n        echo \"<p>$value2 jest podzielne przez 3</p>\";\r\n        break;\r\n    case ($value2 % 5 == 0):\r\n        echo \"<p>$value2 jest podzielne przez 5</p>\";\r\n        break;\r\n    case ($value2 % 7 == 0):\r\n        echo \"<p>$value2 jest podzielne przez 7</p>\";\r\n        break;\r\n    case ($value2 % 9 == 0):\r\n        echo \"<p>$value2 jest podzielne przez 9</p>\";\r\n        break;\r\n    default:\r\n        echo \"<p>Zero dzieli się przez wszystko</p>\";\r\n        break;\r\n}\r\n\r\n\r\nsession_start();\r\nif (!isset($_SESSION[\'visit_counter\'])) {\r\n    $_SESSION[\'visit_counter\'] = 1;\r\n} else {\r\n    $_SESSION[\'visit_counter\']++;\r\n}\r\n\r\necho \"Licznik wizyt: \".$_SESSION[\'visit_counter\'].\"<br>\";\r\n\r\n?>', 1, 'lab4');

